const input = $input.first().json;

// === META VERIFICATION (GET) ===
const hubMode = input['hub.mode'] || (input.query && input.query['hub.mode']);
if (hubMode === 'subscribe') {
  const verifyToken = input['hub.verify_token'] || (input.query && input.query['hub.verify_token']);
  if (verifyToken === 'evolution') {
    const challenge = input['hub.challenge'] || (input.query && input.query['hub.challenge']);
    return [{ json: { isVerification: true, challenge: String(challenge) } }];
  }
  return [];
}

// === META MESSAGE (POST) ===
const body = input.body || input;
if (!body || body.object !== 'whatsapp_business_account') return [];

const entry = body.entry && body.entry[0];
if (!entry || !entry.changes) return [];

const changes = entry.changes[0];
if (!changes || changes.field !== 'messages') return [];

const value = changes.value;
if (!value || !value.messages || !value.messages[0]) return [];

const message = value.messages[0];

// Extrair texto de diferentes tipos de mensagem
let messageText = '';
if (message.type === 'text') {
  messageText = message.text.body;
} else if (message.type === 'button') {
  messageText = message.button.text || message.button.payload || '';
} else if (message.type === 'interactive') {
  if (message.interactive.button_reply) {
    messageText = message.interactive.button_reply.title || '';
  } else if (message.interactive.list_reply) {
    messageText = message.interactive.list_reply.title || '';
  }
} else {
  // Tipo nao suportado (image, audio, video, sticker, etc)
  return [];
}

if (!messageText) return [];

let telefone = message.from;

// Normalizar telefone BR: Meta envia 12 digitos (sem 9o digito)
// Supabase tem 13 digitos (com 9o digito)
if (telefone.startsWith('55') && telefone.length === 12) {
  const ddd = telefone.substring(2, 4);
  const numero = telefone.substring(4);
  telefone = '55' + ddd + '9' + numero;
}

const nomeContato = (value.contacts && value.contacts[0] && value.contacts[0].profile && value.contacts[0].profile.name) || 'Cliente';
const messageId = message.id;
const timestamp = message.timestamp;

return [{ json: { isVerification: false, telefone, nomeContato, messageText, messageId, timestamp } }];

const msg = $('Roteador Meta').first().json;
const leadData = $('Buscar Lead Supabase').first().json;
let lead = null;
if (Array.isArray(leadData)) { lead = leadData[0] || null; }
else if (leadData && leadData.id) { lead = leadData; }

// PRIORIDADE: Usar o nome do lead cadastrado na plataforma (nome_lead)
// Se não encontrar, usa o nome do perfil do WhatsApp (nomeContato)
// Se nenhum estiver disponível, usa 'Cliente'
const nomeContato = lead?.nome_lead || msg.nomeContato || 'Cliente';

const observacaoCrm = lead?.observacao_crm || lead?.empreendimento_nome || null;
const imovelInteresse = observacaoCrm || 'Nao informado';

const leadIdCvcrm = lead?.lead_id_cvcrm || '';
const corretorId = lead?.corretor_id_cvcrm || '';
const statusReativacao = lead?.status_reativacao || 'Desconhecido';
const empreendimentoId = lead?.empreendimento_id || '';
const botaoResposta = msg.messageText || '';
const tipoCampanha = lead?.tipo_campanha || 'reativacao';

return [{ json: {
  chatInput: msg.messageText,
  telefone: msg.telefone,
  nomeContato,
  imovelInteresse,
  leadIdCvcrm,
  corretorId,
  empreendimentoId,
  leadEncontrado: !!lead,
  sessionId: msg.telefone,
  botaoResposta,
  statusReativacao,
  jaReativado: statusReativacao === 'Reativado',
  tipoCampanha
} }];

const aiOutput = $input.first().json.output || $input.first().json.text || '';
const ctx = $('Preparar Contexto').first().json;
const msgUsuario = ctx.chatInput || '';

function normalizar(str) {
  return str.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

const msgNorm = normalizar(msgUsuario);
const botaoNorm = normalizar(ctx.botaoResposta || '');

// ===========================================================
// DICIONÁRIO DE DESINTERESSE
// Cobre botões da campanha de prospecção:
//   "Não tenho interesse no momento."
//   "Não receber mais mensagens."
// E botões da campanha de reativação e variações livres.
// ===========================================================
const palavrasSemInteresse = [
  // Botões exatos da campanha de prospecção (após normalização)
  'nao tenho interesse no momento',
  'nao receber mais mensagens',
  'nao quero receber mais mensagens',
  // Botões da campanha de reativação
  'ja comprei', 'nao busco mais', 'ja encontrei',
  // Variações livres digitadas pelo lead
  'nao preciso', 'nao tenho interesse', 'desistir',
  'nao quero', 'nao busco', 'parar', 'cancelar',
  'sair', 'remover', 'descadastrar', 'parar promocoes',
  'nao enviar', 'nao mandar', 'sem interesse',
  'nao quero mais', 'para de mandar', 'para de enviar',
  'nao me contacte', 'nao me contate', 'me remove',
  'tirar da lista', 'retirar da lista',
  'nao tenho interesse agora', 'por enquanto nao',
  'no momento nao', 'agora nao', 'obrigado mas nao',
  'obrigada mas nao', 'nao preciso agora'
];

let semInteresse = false;
for (const p of palavrasSemInteresse) {
  if (botaoNorm.includes(p) || msgNorm.includes(p)) {
    semInteresse = true;
    break;
  }
}

// Regex para opt-out explícito padrão Meta
if (botaoNorm === 'parar promocoes' || botaoNorm === 'cancelar inscricao') {
  semInteresse = true;
}

const interesse = !semInteresse;
const statusConversa = semInteresse ? 'sem_interesse' : 'interesse_confirmado';

const jaReativado = ctx.jaReativado || false;
const deveReativarCRM = interesse && !jaReativado;

const padroes = [
  { regex: /apartament|casa|terreno|sala|lote|cobertura|studio|kitnet|sobrado|imovel|im[oó]vel|lancamento|lan[cç]amento|planta|dormit[oó]rio|quarto|suite|vaga/i, label: 'Tipo de imovel' },
  { regex: /bairro|regi[aã]o|agua verde|batel|port[aã]o|ecoville|champagnat|juvev[eê]|bacacheri|boa vista|rebou[cç]as|bigorrilho|cabral|alto da gl[oó]ria|merc[eê]s|ah[uú]|santa felicidade|campo comprido|centro|tang[uá]a|pinheirinho|xaxim|boqueir[aã]o|cajuru|tarum[aã]|uberaba|santo in[aá]cio|s[aã]o braz|vila izabel|vista alegre|jardim|hugo lange/i, label: 'Regiao/bairro' },
  { regex: /R\$\s*[\d.,]+|\d+[.,]?\d*\s*(mil|milh[aã]o|milh[oõ]es|reais|k|M)|faixa de|valor|or[cç]amento|investimento|investir|revenda/i, label: 'Faixa de valor' }
];

const infosDetectadas = [];
if (interesse) {
  for (const p of padroes) {
    if (p.regex.test(msgUsuario)) {
      infosDetectadas.push(p.label + ': ' + msgUsuario.substring(0, 120));
    }
  }
}

const infoImportante = infosDetectadas.join(' | ');
const deveAdicionarInteracao = interesse && jaReativado && infoImportante.length > 0;

return [{ json: {
  respostaIA: aiOutput,
  telefone: ctx.telefone,
  nomeContato: ctx.nomeContato,
  leadIdCvcrm: ctx.leadIdCvcrm,
  corretorId: ctx.corretorId,
  empreendimentoId: ctx.empreendimentoId,
  interesse,
  statusConversa,
  mensagemUsuario: ctx.chatInput,
  deveReativarCRM,
  deveAdicionarInteracao,
  infoImportante
} }];

